func shouldUseColor(out io.Writer) bool {
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	if os.Getenv("ENTIRE_GRAPH_FORCE_COLOR") != "" || os.Getenv("FORCE_COLOR") != "" {
