// two lookahead rules (CRLF, and the two-byte UTF-8 form of C1) treat the end of
// a buffer as the end of the input. Renderers here always format a complete
// string before writing it, so a sequence never straddles a Write; were one to,
// the worst outcome is a single visibly escaped CR or a passed-through 0xC2,
// neither of which is a sequence a terminal acts on.
type Writer struct {
	out io.Writer
}

// NewWriter wraps a terminal-bound sink. Wrapping an already-wrapped writer is
// harmless: escaping is idempotent, since every byte it emits is printable ASCII
// that the next pass leaves alone.
func NewWriter(out io.Writer) *Writer {
	return &Writer{out: out}
}

// Write sanitizes p and writes it. It reports len(p) rather than the number of
// bytes actually written, because io.Writer's contract describes progress
// through the CALLER's buffer and a short count would be read as a failed write.
// The common case — output with nothing to escape — passes p through untouched
// and reports the underlying writer's own count.
func (w *Writer) Write(p []byte) (int, error) {
	if !needsEscape(p) {
		return w.out.Write(p)
	}
	safe := appendEscaped(make([]byte, 0, len(p)+escapeHeadroom), p)
	if _, err := w.out.Write(safe); err != nil {
		return 0, err
	}
	return len(p), nil
}

// String neutralizes one value. It exists for the two sinks a writer wrap cannot
// cover: the diff renderer, which must escape a value BEFORE wrapping it in its
// own ANSI color codes, and the --progress line, which shares stderr with the
// progress bar's own cursor control.
func String(value string) string {
	if !needsEscape(value) {
		return value
	}
	return string(appendEscaped(make([]byte, 0, len(value)+escapeHeadroom), value))
}

// Bytes is String for a rendered block. It returns the input itself when there is
// nothing to escape, so the ordinary path neither copies nor allocates.
func Bytes(value []byte) []byte {
	if !needsEscape(value) {
		return value
	}
	return appendEscaped(make([]byte, 0, len(value)+escapeHeadroom), value)
}

// escapeHeadroom is the slack the output buffer starts with. It is a guess at how
// much a hostile string grows, not a bound; append handles the rest.
const escapeHeadroom = 16

const hexDigits = "0123456789abcdef"

// text is the shape both entry points share. Sanitizing reads by index and never
// slices, so one implementation serves strings and byte slices without either
// caller converting — and a conversion here would allocate a copy of every
// payload the tool prints.
type text interface {
	~string | ~[]byte
}

// escapedAt reports how a byte at index i must be treated: keep it (0), escape
// just it (1), or escape it together with the byte that follows (2). The width is
// what lets the scan and the rewrite agree without duplicating the rules.
func escapedAt[T text](data T, i int) int {
	character := data[i]
