		return 1
	case character == 0xc2 && i+1 < len(data) && data[i+1] >= 0x80 && data[i+1] <= 0x9f:
		// The C1 controls in their two-byte UTF-8 form. U+009B is CSI, which a
		// terminal in UTF-8 mode acts on exactly as it acts on "ESC [".
		return 2
	default:
		return 0
	}
}

func needsEscape[T text](data T) bool {
	for i := 0; i < len(data); i++ {
		if escapedAt(data, i) > 0 {
			return true
		}
	}
	return false
}

// appendEscaped writes data to dst with every control byte replaced by its Go
// literal form — \x1b for C0 and DEL,  for C1 — so the escape reads as
// source to the developer who finds it in a log.
func appendEscaped[T text](dst []byte, data T) []byte {
	for i := 0; i < len(data); i++ {
		switch escapedAt(data, i) {
		case 1:
